"""Compose the per-ξ distortion histograms (already Haoyang-formatted, generated by
the simulation pipeline) into 1x3 rows for ξ = 0.3, 0.1, 0.05."""
import os
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import matplotlib.image as mpimg

HERE = os.path.dirname(os.path.abspath(__file__))
FIG = os.path.join(HERE, "figures")
XIS = [("0.300", "ξ = 0.3"), ("0.100", "ξ = 0.1"), ("0.050", "ξ = 0.05")]

for kind in ("climate_dist", "dmg_dist"):
    fig, axes = plt.subplots(1, 3, figsize=(16.5, 4.6))
    for a, (xi, lab) in zip(axes, XIS):
        a.imshow(mpimg.imread(os.path.join(FIG, f"{kind}_{xi}.png")))
        a.set_title(lab, fontsize=15)
        a.axis("off")
    fig.tight_layout()
    out = os.path.join(FIG, f"{kind}_row.png")
    fig.savefig(out, dpi=150, bbox_inches="tight")
    print("wrote", out)
